{"command": "python3 -c "
# Note name to XM note integer mapping:
# In XM: note 1 = C-0, note 13 = C-1, note 25 = C-2, note 37 = C-3, note 49 = C-4, note 61 = C-5, note 73 = C-6, note 85 = C-7, note 97 = Off
notes = ['C-', 'C#', 'D-', 'D#', 'E-', 'F-', 'F#', 'G-', 'G#', 'A-', 'A#', 'B-']
name_to_int = {}
int_to_name = {}

for oct in range(8):
    for i, n in enumerate(notes):
        num = 1 + oct * 12 + i
        s = f'{n}{oct}'
        name_to_int[s] = num
        int_to_name[num] = s

print('C-2:', name_to_int['C-2'], 'D-2:', name_to_int['D-2'])
print('C-4:', name_to_int['C-4'], 'A-4:', name_to_int['A-4'], 'D-4:', name_to_int['D-4'])
print('C-5:', name_to_int['C-5'], 'D-5:', name_to_int['D-5'])
""}

